import{_ as a,o as s,c as l,a0 as o}from"./chunks/framework.CShDTZbC.js";const v=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Larx Legal","text":"The collaboration platform for small law firms","tagline":"Share files, collaborate on cases and manage clients — all in one secure place, built for legal work.","actions":[{"theme":"brand","text":"Book a demo","link":"/about"},{"theme":"alt","text":"Explore features","link":"/features"}]},"features":[{"icon":"📁","title":"Filesharing","details":"Share documents securely with clients and colleagues, with full control over who sees what.","link":"/filesharing","linkText":"Find out more"},{"icon":"🤝","title":"Collaboration","details":"Chat, notes and agenda per dossier — firm and client working from one source of truth.","link":"/collaboration","linkText":"Find out more"},{"icon":"👥","title":"Client management","details":"Full control over clients, teams and dossier access — managed from one secure dashboard.","link":"/client-management","linkText":"Find out more"}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),i={name:"index.md"};function n(t,e,r,c,d,h){return s(),l("div",null,[...e[0]||(e[0]=[o('<section class="lx-section lx-logos"><p class="lx-social-proof">Trusted by small law firms across the Netherlands</p><div class="lx-logo-strip"><span class="lx-logo-placeholder">Client logo</span><span class="lx-logo-placeholder">Client logo</span><span class="lx-logo-placeholder">Client logo</span><span class="lx-logo-placeholder">Client logo</span><span class="lx-logo-placeholder">Client logo</span><span class="lx-logo-placeholder">Client logo</span></div></section><section class="lx-section"><div class="lx-section-head"><h2>Everything your firm needs, nothing it doesn&#39;t</h2><p>One platform for the daily work of a small law firm — from the first client contact to the closed case file.</p></div><div class="lx-showcase"><div class="lx-showcase-text"><h3>Filesharing</h3><div class="lx-mini-feature"><h4>Secure by default</h4><p>Every document is encrypted and access-controlled. No more sensitive files in email attachments.</p></div><div class="lx-mini-feature"><h4>Client portal</h4><p>Clients upload and download their documents in a branded portal — onboarding takes one email.</p></div><div class="lx-mini-feature"><h4>Version history</h4><p>Always know which version is current, and roll back when needed.</p></div><a class="lx-link" href="/filesharing">Find out more →</a></div><div class="lx-showcase-image">Screenshot placeholder</div></div><div class="lx-showcase lx-showcase--reverse"><div class="lx-showcase-text"><h3>Collaboration</h3><div class="lx-mini-feature"><h4>One dossier per case</h4><p>Chat, documents, notes and agenda together in one secure dossier — the single source of truth for firm and client.</p></div><div class="lx-mini-feature"><h4>Chat like WhatsApp</h4><p>Group chat with everyone involved, or private one-on-one — with rich text, shared documents and read receipts.</p></div><div class="lx-mini-feature"><h4>Always in the loop</h4><p>Email and push notifications on every update, and unread counters that take you straight to what&#39;s new.</p></div><a class="lx-link" href="/collaboration">Find out more →</a></div><div class="lx-showcase-image">Screenshot placeholder</div></div><div class="lx-showcase"><div class="lx-showcase-text"><h3>Client management</h3><div class="lx-mini-feature"><h4>Full access control</h4><p>The firm decides who has access to which dossier — clients can&#39;t add or remove people themselves.</p></div><div class="lx-mini-feature"><h4>One management dashboard</h4><p>Manage clients, teams and dossiers from one secure place, with every action logged.</p></div><div class="lx-mini-feature"><h4>The relationship in one place</h4><p>Contracts, invoices and client profiles — including industry and legal areas, ready for targeted marketing.</p></div><a class="lx-link" href="/client-management">Find out more →</a></div><div class="lx-showcase-image">Screenshot placeholder</div></div></section><section class="lx-section"><div class="lx-banner"><div class="lx-banner-text"><span class="lx-badge">✨ New</span><h3>Introducing the Larx client portal</h3><p>Give your clients a secure, professional place to exchange documents and follow the progress of their case.</p><a class="lx-link" href="/features">Learn more →</a></div><div class="lx-banner-image">Illustration placeholder</div></div></section><section class="lx-section"><div class="lx-section-head"><h2>Built for everyone in your firm</h2><p>Larx adapts to how each person in a small firm actually works.</p></div><div class="lx-grid lx-grid--4"><div class="lx-card"><div class="lx-card-image">Photo placeholder</div><h4>The partner</h4><p>Oversees every matter and keeps the firm running — without chasing status updates.</p></div><div class="lx-card"><div class="lx-card-image">Photo placeholder</div><h4>The associate</h4><p>Drafts, reviews and collaborates on documents without version chaos.</p></div><div class="lx-card"><div class="lx-card-image">Photo placeholder</div><h4>The office manager</h4><p>Handles intake, scheduling and files with everything in one place.</p></div><div class="lx-card"><div class="lx-card-image">Photo placeholder</div><h4>The client</h4><p>Shares documents and follows their case through a simple, secure portal.</p></div></div><p class="lx-section-foot"><a class="lx-link" href="/about">Get to know more advantages →</a></p></section><section class="lx-section"><div class="lx-section-head"><h2>What our customers say</h2><p>Law firms of all kinds use Larx every day. Here&#39;s what they think.</p></div><div class="lx-grid lx-grid--2"><a class="lx-card lx-testimonial" href="/about"><p class="lx-quote">&quot;Since we switched to Larx, we spend far less time emailing documents back and forth. Clients love the portal.&quot;</p><div class="lx-person"><span class="lx-avatar">AB</span><span><strong>Anna B.</strong><br>Partner, family law firm</span></div></a><a class="lx-card lx-testimonial" href="/about"><p class="lx-quote">&quot;When someone leaves a client, I revoke their access in one click — and I can prove it. That kind of control used to be impossible.&quot;</p><div class="lx-person"><span class="lx-avatar">MK</span><span><strong>Mark K.</strong><br>Founder, employment law practice</span></div></a><a class="lx-card lx-testimonial" href="/about"><p class="lx-quote">&quot;Finally software that doesn&#39;t need a manual. Our whole office was up and running in an afternoon.&quot;</p><div class="lx-person"><span class="lx-avatar">SV</span><span><strong>Sophie V.</strong><br>Office manager</span></div></a><a class="lx-card lx-testimonial" href="/about"><p class="lx-quote">&quot;Our clients now upload documents themselves — securely. That used to be our biggest headache.&quot;</p><div class="lx-person"><span class="lx-avatar">JD</span><span><strong>Jeroen D.</strong><br>Partner, real estate law</span></div></a></div><p class="lx-section-foot"><a class="lx-link" href="/about">Read all success stories →</a></p></section><section class="lx-section"><div class="lx-section-head"><h2>Why law firms choose Larx</h2></div><div class="lx-grid lx-grid--4 lx-why"><div><h4>All-in-one</h4><p>Files, collaboration and client management in a single platform — no more juggling tools.</p></div><div><h4>Built for legal</h4><p>Designed around how small law firms actually work, not adapted from generic software.</p></div><div><h4>Personal support</h4><p>Real people who know the product and understand legal practice.</p></div><div><h4>GDPR compliant</h4><p>Your data and your clients&#39; data stay safe, compliant and in Europe.</p></div></div></section><section class="lx-section"><div class="lx-banner lx-cta"><div class="lx-banner-text"><h3>See Larx in action</h3><ul class="lx-checklist"><li>✓ Free personal demo, no strings attached</li><li>✓ Set up in one afternoon</li><li>✓ No credit card required</li></ul><a class="lx-button" href="/about">Book a demo</a></div><div class="lx-banner-image">Screenshot placeholder</div></div></section>',7)])])}const u=a(i,[["render",n]]);export{v as __pageData,u as default};
